      "depends_on": [2, 3]
    },
    {
      "id": 5,
      "claim": "A pressure difference of ~30 kPa is sufficient to crush an empty flexible PET bottle.",
      "evidence": "Typical PET bottles collapse under external‑to‑internal pressure differentials of ~10 kPa; 30 kPa exceeds this by a large margin.",
      "weight": 0.15,
      "depends_on": [4]
    },
    {
      "id": 6,
      "claim": "Temperature change between the mountain top and the valley is modest and cannot offset the pressure difference.",
      "evidence": "A 10 °C temperature change alters gas pressure by ≈3 % (≈3 kPa) via the ideal‑gas law, far smaller than the ~30 kPa pressure differential.",
